<script>
 import ExportResults from './ExportResults.svelte';
 import TaskOutputActions from './TaskOutputActions.svelte';
 import {stopChat,undoChat,undoReceipt,retryChat,confirmChat,cancelChatConfirmation} from '../stores/chat.svelte';import Button from '../ui/Button.svelte';import ConfirmRow from './ConfirmRow.svelte';
 let {row,onshow=()=>{},onexport=()=>{}}=$props();let expanded=$state(false);
 const sources={mention:'@引用',selected:'已选',editor:'当前图',filter:'筛选结果'};
 const plan=$derived((row.summary||'').replaceAll('local_plan','本地处理步骤').replaceAll('fit_ratio','调整比例').replaceAll('cutout','抠图').replaceAll('white','白底').replaceAll('center','居中').replaceAll('generate','生成图片').replaceAll('export','导出').replaceAll('trash','移入回收站'));
 const labels={resolving:'正在确定对象',planning:'正在制定方案',awaiting_confirm:'等待确认',running:'正在处理',done:'完成',partial:'部分完成',failed:'处理失败',cancelled:'已停止'};
</script>
<div class="exec-row" data-state={row.state} data-receipt={row.receipt?'true':undefined} aria-live="polite">{#if row.receipt}<p>{row.state==='done'?'✓ ':row.state==='failed'?'处理失败 · ':row.state==='partial'?'部分完成 · ':''}{row.summary}{row.undone?' · 已撤销':''}</p>{#if row.receiptAction&&!row.undone&&(row.receiptAction.kind==='project-delete'||typeof row.receiptAction.callback==='function')}<Button disabled={row.actionBusy} onclick={()=>undoReceipt(row)}>{row.actionBusy?'正在撤销…':row.receiptAction.label||'撤销'}</Button>{/if}{#if row.actionError}<p role="alert">{row.actionError}</p>{/if}{#if row.exportReport}<ExportResults report={row.exportReport} attempted={row.attempted} cancelled={row.cancelled}/>{/if}{:else}<p>对象：{row.command?.operations[0]?.source==='text'?'纯文本生图':sources[row.context.resolvedTarget.source]} {row.total} 张</p>
 {#if row.summary}<button class="exec-summary" aria-expanded={expanded} onclick={()=>expanded=!expanded}>方案：{plan}</button>{#if expanded}<pre>{JSON.stringify(row.command?.operations||row.operations||row.context.resolvedTarget,null,2)}</pre>{/if}{/if}
 {#if row.state==='awaiting_confirm'}<ConfirmRow message={row.confirmation?.message||''} oncontinue={()=>confirmChat(row)} oncancel={()=>cancelChatConfirmation(row)}/>
 {:else if row.state==='running'}<div class="exec-progress"><progress max={row.total||1} value={row.done}></progress><span>{row.queuePosition!=null?`排队：前面还有 ${row.queuePosition} 个`:`${row.done} / ${row.total}`}</span><Button onclick={()=>stopChat(row)}>停止 Esc</Button></div>{#each row.failures||[] as failure}<p>{failure.message}</p>{/each}
 {:else if row.state==='done'}<p>✓ 完成 {row.done} 张{row.undone?' · 已撤销':''}</p>{#if row.batchId&&row.undoable!==false}<Button onclick={()=>undoChat(row)}>{row.undone?'重做':'撤销'}</Button>{/if}{#if row.resultAssetIds?.length}<Button onclick={()=>onexport(row)}>导出</Button><Button onclick={()=>onshow(row)}>在素材库中查看</Button>{/if}

 {#each row.warnings||[] as warning}<p>{warning}</p>{/each}
 {:else if row.state==='partial'}<p>完成 {row.done} 张 · 失败 {row.failed} 张</p><Button onclick={()=>retryChat(row,true)}>重试失败项</Button><details><summary>查看原因</summary>{#each row.failures||[] as failure}<p>{failure.message}</p>{/each}</details>{#if row.batchId&&row.undoable!==false}<Button onclick={()=>undoChat(row)}>撤销已完成项</Button>{/if}
 {:else if row.state==='failed'||row.state==='cancelled'}<p>{row.error||labels[row.state]}</p>{#if row.resultAssetIds?.length}<Button onclick={()=>onshow(row)}>查看已完成结果</Button>{#if row.batchId&&row.undoable!==false}<Button onclick={()=>undoChat(row)}>撤销已完成项</Button>{/if}{/if}<Button onclick={()=>retryChat(row)}>重试</Button>
 {:else}<p>{labels[row.state]}…</p><Button onclick={()=>stopChat(row)}>停止 Esc</Button>{/if}
<TaskOutputActions task={{id:row.taskId||row.requestId,projectId:row.projectId,outputs:row.outputs||[],undone:row.undone}}/>{/if}</div>
<style>.exec-row{padding:12px 0;border-top:1px solid var(--border);border-bottom:1px solid var(--border);font-size:12px;color:var(--text)}.exec-row p{margin:0 0 8px;line-height:1.7;overflow-wrap:anywhere}.exec-summary{color:var(--text-dim);background:transparent;border:0;padding:0 0 8px;font-size:12px;max-width:100%;overflow-wrap:anywhere;text-align:left;cursor:pointer}.exec-summary:hover{color:var(--accent)}.exec-summary:active{color:var(--text)}.exec-summary:focus-visible{outline:2px solid var(--focus)}.exec-row pre{max-height:200px;overflow:auto;white-space:pre-wrap;font-size:11px}.exec-progress{display:flex;align-items:center;flex-wrap:wrap;gap:8px}.exec-progress progress{flex:1;min-width:50px;accent-color:var(--accent)}.exec-row details{padding:8px 0}.exec-row summary{cursor:pointer}.exec-row :global(.ui-button){font-size:12px;margin:2px}</style>
